## 5\. 具体的なコード例

### 5.1 DO ベース Agent クラス定義（最小）

```typescript
import { Agent, routeAgentRequest, callable } from "agents";

type State = {
  lastCheckedAt: number;
  processedIds: string[];
};

export class InboxWatcherAgent extends Agent<Env, State> {
  initialState: State = { lastCheckedAt: 0, processedIds: [] };

  async onStart() {
    // 初回起動で cron-like タイマーをセット（15 分おき）
    await this.schedule("*/15 * * * *", "pollInbox", {});
  }

  async pollInbox() {
    const since = this.state.lastCheckedAt;
    const items = await this.fetchInboxSince(since);

    for (const item of items) {
      if (this.state.processedIds.includes(item.id)) continue;
      await this.handleItem(item);
      this.setState({
        ...this.state,
        processedIds: [...this.state.processedIds, item.id],
      });
    }
    this.setState({ ...this.state, lastCheckedAt: Date.now() });
  }

  @callable()
  async status(): Promise<{ last: number; count: number }> {
    return {
      last: this.state.lastCheckedAt,
      count: this.state.processedIds.length,
    };
  }

  private async handleItem(item: InboxItem) {
    const verdict = await this.env.AI.run("@cf/meta/llama-3.3-70b-instruct-fp8-fast", {
      prompt: `Classify: ${item.subject}`,
    });
    await this.env.OUTBOUND.fetch("https://slack.com/api/chat.postMessage", {
      method: "POST",
      body: JSON.stringify({ text: verdict.response }),
    });
  }
}

export default {
  async fetch(request: Request, env: Env) {
    return (
      (await routeAgentRequest(request, env)) ??
      new Response("Not found", { status: 404 })
    );
  },
};
```

### 5.2 Alarm でポーリング（GitHub / Linear / Obsidian 監視例）

```typescript
export class CrossSourceWatcher extends Agent<Env, WatcherState> {
  initialState: WatcherState = { cursors: {} };

  async onStart() {
    await this.schedule("*/10 * * * *", "pollAll", {});
  }

  async pollAll() {
    await Promise.all([
      this.pollGitHub(),
      this.pollLinear(),
      this.pollObsidian(),
    ]);
  }

  async pollGitHub() {
    const since = this.state.cursors.github ?? new Date(Date.now() - 86400_000).toISOString();
    const res = await this.env.OUTBOUND.fetch(
      `https://api.github.com/notifications?since=${since}`
    );
    const events: GhEvent[] = await res.json();
    for (const ev of events) await this.digest("github", ev);
    this.setState({
      ...this.state,
      cursors: { ...this.state.cursors, github: new Date().toISOString() },
    });
  }

  async pollLinear() {
    // GraphQL で updatedAt > cursor の issue を取得
  }

  async pollObsidian() {
    // sandbox.watch() からの SSE を別経路で受ける or R2 にエクスポートされた vault を diff
  }

  private async digest(source: string, ev: unknown) {
    // LLM で要約 → Vectorize に upsert → 重要なら Agents Inbox に積む
  }
}
