## 5\. 具体的なコード例

### 5.1 最小の Workflow クラス

```typescript
import {
  WorkflowEntrypoint,
  WorkflowStep,
  WorkflowEvent,
} from "cloudflare:workers";

type Params = { userId: string };

interface Env {
  DB: D1Database;
  R2: R2Bucket;
}

export class MyPipeline extends WorkflowEntrypoint<Env, Params> {
  async run(event: WorkflowEvent<Params>, step: WorkflowStep) {
    const user = await step.do("fetch-user", async () => {
      const row = await this.env.DB
        .prepare("SELECT * FROM users WHERE id = ?")
        .bind(event.payload.userId)
        .first();
      if (!row) throw new Error("not found");
      return row;
    });

    await step.sleep("wait-one-day", "1 day");

    await step.do("send-followup", async () => {
      await fetch("https://api.example.com/email", {
        method: "POST",
        body: JSON.stringify({ to: user.email, template: "followup" }),
      });
    });
  }
}
```

### 5.2 [step.do](<http://step.do>) のパターン集

```typescript
// 基本形
const result = await step.do("step-name", async () => {
  return { data: "value" }; // 戻り値は自動永続化
});

// リトライポリシー
const result = await step.do("call-api", {
  retries: {
    limit: 5,
    delay: "5 seconds",
    backoff: "exponential", // "constant" | "linear" | "exponential"
  },
  timeout: "15 minutes",
}, async () => {
  const res = await fetch("https://api.example.com/data");
  if (!res.ok) throw new Error(`API error: ${res.status}`);
  return res.json();
});

// Step Context(2026-03-06〜)
await step.do("with-context", async (ctx) => {
  // ctx.attempt     : 試行回数(1 = 初回、2 = 1st retry ...)
  // ctx.step.name   : "with-context"
  // ctx.step.count  : この name の何回目の invoke か
  // ctx.config      : 解決済み設定
  console.log(`[${ctx.step.name}#${ctx.step.count}] attempt=${ctx.attempt}`);
  if (ctx.attempt === ctx.config.retries.limit) {
    // 最終リトライで fallback API に切り替え
    return fetch("https://fallback.example.com/data");
  }
  return fetch("https://primary.example.com/data");
});

// ループ内 step(ctx.step.count でどの iteration か判別)
for (const item of items) {
  await step.do("process-item", async (ctx) => {
    console.log(`item ${ctx.step.count}/${items.length} (attempt ${ctx.attempt})`);
    await processItem(item);
  });
}

// ReadableStream 出力(1 MiB 制限を回避)
const stream = await step.do("fetch-large", async () => {
  const obj = await this.env.R2.get("big.parquet");
  return obj.body; // ReadableStream をそのまま返す
});
await step.do("process-stream", async () => {
  const reader = stream.getReader();
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    await processChunk(value);
  }
});

// Fan-out / Fan-in
const urls = await step.do("list-urls", async () => getUrls());
const results = await Promise.all(
  urls.map((url, i) =>
    step.do(`fetch-${i}`, async () => {
      const res = await fetch(url);
      return res.json();
    })
  ),
);
const merged = await step.do("merge", async () => aggregate(results));
```

### 5.3 step.sleep / step.waitForEvent

```typescript
// 長期スリープ(最大 365 日)
await step.sleep("daily-wait", "1 day");
await step.sleep("weekly-wait", "7 days");
await step.sleepUntil("absolute", new Date("2026-12-25T00:00:00Z"));

// 外部イベント待ち — 承認フロー
const approval = await step.waitForEvent<{ approved: boolean; reviewer: string }>(
  "wait-for-approval",
  { timeout: "24 hours" }
);

if (!approval.approved) {
  await step.do("reject-notification", async () => {
    await notifyRejection(approval.reviewer);
  });
  return;
}

// 外部からのイベント送信(別 Worker や API から)
const instance = await env.MY_WORKFLOW.get(instanceId);
await instance.sendEvent({
  type: "wait-for-approval",
  payload: { approved: true, reviewer: "alice@example.com" },
});
```

### 5.4 リトライポリシー設定の指針

| シナリオ | limit | delay | backoff |
| -- | -- | -- | -- |
| 外部 API 呼び出し | 3〜5 | "10 seconds" | exponential |
| DB 書き込み | 3 | "5 seconds" | constant |
| 通知送信 | 2 | "30 seconds" | linear |
| 冪等でない処理 | 0 | — | — |
| 即座に次の step に進めない重要処理 | 10 | "1 minute" | exponential(最大 1 時間程度まで) |

### 5.5 非決定性の閉じ込めパターン

```typescript
// NG: workflow 本体で直接呼ぶとリプレイ時に値がズレる
async run(event, step) {
  const now = Date.now(); // replay 時に違う値が返る可能性
  const id = crypto.randomUUID(); // 毎回異なる
  const res = await fetch("https://api..."); // 直接 I/O は NG
}

// OK: step.do 内に閉じ込める → 結果が永続化され、replay 時は同じ値
async run(event, step) {
  const now = await step.do("timestamp", async () => Date.now());
  const id = await step.do("generate-id", async () => crypto.randomUUID());
  const data = await step.do("fetch-data", async () => {
    const res = await fetch("https://api...");
    return res.json();
  });
}
```

**ルール:**

* `Date.now()` / `new Date()` / `performance.now()` → `step.do` 内
* `Math.random()` / `crypto.randomUUID()` / `crypto.getRandomValues()` → `step.do` 内
* 外部 `fetch` / DB アクセス / R2 アクセス → `step.do` 内
* `this.env` のアクセス(読み取りのみ)→ どこでも OK
* 普通の変数代入・if 分岐・ループ → どこでも OK(replay で同じ結果になるため)

### 5.6 起動・状態管理

```typescript
// Worker の fetch ハンドラから起動
async fetch(request, env) {
  const instance = await env.MY_WORKFLOW.create({
    id: crypto.randomUUID(), // optional、省略で自動採番
    params: { userId: "abc-123" },
  });
  return Response.json({ id: instance.id, status: await instance.status() });
}

// Cron Trigger から起動
async scheduled(event, env) {
  await env.MY_WORKFLOW.create({ params: {} });
}

// 状態確認・制御
const instance = await env.MY_WORKFLOW.get(id);
const status = await instance.status();
// status.status: "queued" | "running" | "paused" | "complete" | "errored" | "terminated"
await instance.pause();
await instance.resume();
await instance.terminate();
```

